// Turn any bank CSV export into clean transactions (date, description, merchant, amount)
const form = $('Bank statement upload form').first().json;
const dayFirst = !String(form.date_format || '').startsWith('Month');
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && !r.error);
const keys = [...new Set(rows.flatMap(r => Object.keys(r)))]; // CSV readers drop empty cells, so collect headers from every row
const find = (...pats) => keys.find(k => pats.some(p => p.test(k.trim())));
const kDate = find(/^(transaction |posting |value )?date$/i, /date/i, /posted/i);
const kDesc = find(/desc/i, /narrative/i, /details/i, /memo/i, /payee/i, /merchant/i, /^name$/i, /reference/i);
const kAmt = find(/^amount/i, /amount/i, /^value$/i);
const kOut = find(/debit/i, /paid out/i, /money out/i, /withdraw/i, /^out$/i);
const kIn = find(/credit/i, /paid in/i, /money in/i, /deposit/i, /^in$/i);
const num = v => {
  if (v === undefined || v === null || String(v).trim() === '') return null;
  let s = String(v).trim();
  const neg = /^\(.*\)$/.test(s) || /^-/.test(s) || /-$/.test(s) || /\bDR$/i.test(s);
  s = s.replace(/[^0-9.,]/g, '');
  if (/,\d{1,2}$/.test(s) && !/\.\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return isNaN(n) ? null : (neg ? -Math.abs(n) : n);
};
const pad = n => String(n).padStart(2, '0');
const toIso = v => {
  const s = String(v ?? '').trim(); let m;
  if ((m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/))) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  if ((m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/))) {
    const y = m[3].length === 2 ? '20' + m[3] : m[3];
    const d = dayFirst ? m[1] : m[2], mo = dayFirst ? m[2] : m[1];
    return `${y}-${pad(mo)}-${pad(d)}`;
  }
  const d = new Date(s); return isNaN(d) ? '' : d.toISOString().slice(0, 10);
};
const clean = d => String(d ?? '').toUpperCase()
  .replace(/\d{1,2}[\/.\-]\d{1,2}([\/.\-]\d{2,4})?/g, ' ')
  .replace(/\b(CARD PAYMENT|CARD|VISA|MASTERCARD|DEBIT|CREDIT|POS|PAYMENT TO|PAYMENT FROM|PAYMENT|PURCHASE|CONTACTLESS|DIRECT DEBIT|STANDING ORDER|DD|SO|FPI|FPO|BGC|TFR|BACS|REF|ON|TO|FROM)\b/g, ' ')
  .replace(/\*\S*/g, ' ').replace(/#\S*/g, ' ').replace(/\b[A-Z]*\d[A-Z\d]{3,}\b/g, ' ')
  .replace(/[^A-Z&' .-]/g, ' ').replace(/\s+/g, ' ').trim().replace(/(\s+[A-Z]{1,4})?[\s.-]+$/, '').slice(0, 40) || 'UNKNOWN';
const hash = s => { let h = 5381; for (const c of s) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(36); };
if (!kDate || !kDesc || (!kAmt && !kOut && !kIn)) {
  return [{ json: { ok: false, reason: `Could not find date, description and amount columns. Columns found: ${keys.join(', ') || 'none'}` } }];
}
const seen = {};
const out = [];
rows.forEach((r, i) => {
  let amount = kAmt ? num(r[kAmt]) : null;
  if (amount === null) {
    const o = kOut ? num(r[kOut]) : null, n = kIn ? num(r[kIn]) : null;
    if (o) amount = -Math.abs(o); else if (n) amount = Math.abs(n);
  }
  const date = toIso(r[kDate]);
  const description = String(r[kDesc] ?? '').trim();
  if (amount === null || amount === 0 || !date || !description) return;
  let id = hash(`${date}|${amount.toFixed(2)}|${description}`);
  seen[id] = (seen[id] || 0) + 1;
  if (seen[id] > 1) id += '-' + seen[id];
  out.push({ json: { ok: true, txn_id: id, date, description, merchant: clean(description),
    amount: Math.round(amount * 100) / 100, direction: amount < 0 ? 'out' : 'in', currency: form.currency || 'GBP', source_row: i + 2 } });
});
if (!out.length) return [{ json: { ok: false, reason: 'The file had the right columns but no rows with a valid date and a non-zero amount.' } }];
return out;

// One line per unique merchant, 40 merchants per AI call (keeps free-tier usage low)
const txns = $input.all().map(i => i.json);
const by = {};
for (const t of txns) {
  const m = by[t.merchant] || (by[t.merchant] = { merchant: t.merchant, count: 0, total: 0, ins: 0, sample: t.description });
  m.count++; m.total += t.amount; if (t.amount > 0) m.ins++;
}
const list = Object.values(by).sort((a, b) => Math.abs(b.total) - Math.abs(a.total));
const business = $('Bank statement upload form').first().json.business || 'a small business';
const batches = [];
for (let i = 0; i < list.length; i += 40) {
  const lines = list.slice(i, i + 40).map((m, j) =>
    `${i + j + 1}. ${m.merchant} | money ${m.ins > m.count / 2 ? 'IN' : 'OUT'} | ${m.count} txn | total ${m.total.toFixed(2)} | e.g. "${m.sample.slice(0, 60)}"`);
  batches.push({ json: { skip_ai: false, business, merchant_count: Math.min(40, list.length - i), merchants: lines.join('\n') } });
}
return batches;

// Map AI categories back onto every transaction and flag rows a human should check
const INCOME = ["Sales", "Other income", "Refunds received", "Transfers"];
const map = {};
for (const it of $input.all()) for (const r of (it.json.output?.results || [])) map[String(r.merchant).trim().toUpperCase()] = r;
return $('Normalise transactions').all().map(({ json: t }) => {
  const r = map[t.merchant] || {};
  let category = r.category || 'Uncategorised';
  let confidence = typeof r.confidence === 'number' ? r.confidence : 0;
  let check = '';
  if (t.direction === 'out' && ['Sales', 'Other income'].includes(category)) check = 'Money out labelled as income';
  if (t.direction === 'in' && !INCOME.includes(category) && category !== 'Uncategorised') check = 'Money in labelled as an expense';
  if (/-\d+$/.test(t.txn_id)) check = 'Possible duplicate: same date, amount and description as another row';
  const needs_review = category === 'Uncategorised' || confidence < 0.7 || !!check;
  return { json: { txn_id: t.txn_id, date: t.date, description: t.description, merchant: t.merchant, amount: t.amount,
    currency: t.currency, category, confidence: Math.round(confidence * 100) / 100, needs_review: needs_review ? 'YES' : '',
    review_note: check || (needs_review ? 'Low confidence' : ''), ai_reason: r.reason || '', corrected_category: '' } };
});

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Build the summary shown on the form's result page
const rows = $('Apply categories to transactions').all().map(i => i.json);
const cur = rows[0]?.currency || '';
const f = n => `${cur} ${n.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const income = rows.filter(r => r.amount > 0 && r.category !== 'Transfers').reduce((s, r) => s + r.amount, 0);
const spend = rows.filter(r => r.amount < 0 && r.category !== 'Transfers').reduce((s, r) => s - r.amount, 0);
const cats = {};
for (const r of rows) (cats[r.category] = cats[r.category] || { n: 0, total: 0 }), cats[r.category].n++, cats[r.category].total += r.amount;
const merch = {};
for (const r of rows.filter(r => r.amount < 0 && r.category !== 'Transfers')) merch[r.merchant] = (merch[r.merchant] || 0) - r.amount;
const top = Object.entries(merch).sort((a, b) => b[1] - a[1]).slice(0, 5);
const review = rows.filter(r => r.needs_review === 'YES').length;
const dates = rows.map(r => r.date).sort();
const catRows = Object.entries(cats).sort((a, b) => a[1].total - b[1].total)
  .map(([c, v]) => `<tr><td>${esc(c)}</td><td style="text-align:right">${v.n}</td><td style="text-align:right">${f(v.total)}</td></tr>`).join('');
const html = `<h3>${rows.length} transactions categorised (${dates[0]} to ${dates[dates.length - 1]})</h3>
<p><b>Income:</b> ${f(income)} &nbsp; <b>Spending:</b> ${f(spend)} &nbsp; <b>Net:</b> ${f(income - spend)} <br><small>Transfers between your own accounts are excluded.</small></p>
<p><b>${review}</b> row(s) are marked <i>needs_review</i> in your sheet. Fix them in the <i>corrected_category</i> column.</p>
<table style="width:100%;border-collapse:collapse"><tr><th align="left">Category</th><th>Txns</th><th>Total</th></tr>${catRows}</table>
<p><b>Top suppliers:</b> ${top.map(([m, v]) => `${esc(m)} (${f(v)})`).join(', ') || 'none'}</p>`;
return [{ json: { html, income, spend, review, count: rows.length } }];
